package com.example.cvd;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import jakarta.annotation.*;
import java.nio.file.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.concurrent.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.core.io.FileSystemResource;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/reports")
public class ReportApi {
 final DataStore db;final ReportData data;final ReportAi ai;final ReportRenderer renderer;final Path root;final TransactionTemplate tx;
 final ExecutorService workers=Executors.newFixedThreadPool(2);final Semaphore slots=new Semaphore(2);
 public ReportApi(DataStore db,ReportData data,ReportAi ai,ReportRenderer renderer,@Value("${CVD_REPORT_DIR:/data/reports}")String root){this.db=db;this.data=data;this.ai=ai;this.renderer=renderer;this.root=Path.of(root);this.tx=new TransactionTemplate(new DataSourceTransactionManager(db.pg.getDataSource()));}
 @PostConstruct void init()throws Exception{Files.createDirectories(root);db.pg.execute("""
 CREATE TABLE IF NOT EXISTS ai_reports(id uuid PRIMARY KEY,owner_id uuid NOT NULL,request_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days',equipment text NOT NULL,period text NOT NULL,language text NOT NULL,cutoff timestamptz NOT NULL,status text NOT NULL,error_code text,snapshot jsonb,snapshot_hash text,analysis jsonb,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,request_id))
 """);db.pg.execute("CREATE INDEX IF NOT EXISTS ai_reports_owner ON ai_reports(owner_id,created_at DESC)");db.pg.update("UPDATE ai_reports SET status='failed',error_code='interrupted',updated_at=now() WHERE status IN ('queued','collecting','analyzing','rendering')");}
 @PreDestroy void stop(){workers.shutdownNow();}
 @GetMapping("/config") public Map<String,Object> config(){return Map.of("configured",ai.configured(),"maxDays",30,"retentionDays",30,"maxRows",ReportData.MAX_ROWS,"maxBytes",ReportRenderer.MAX_BYTES);}
 static String validId(String id){try{return UUID.fromString(id).toString();}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"invalid report id");}}
 @PostMapping public Map<String,Object> create(@RequestBody Map<String,String> body){
  String owner=AccessSessions.actor().id(),request=validId(body.get("requestId")),eq=body.getOrDefault("equipmentId","all"),period=body.getOrDefault("period","today"),lang=body.getOrDefault("language","zh-TW");ReportData.equipment(eq);Instant cutoff=Instant.now().truncatedTo(ChronoUnit.SECONDS);ReportData.start(period,cutoff);if(!Set.of("zh-TW","en","ja").contains(lang))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"invalid language");
  String id=tx.execute(t->{db.pg.execute("SELECT pg_advisory_xact_lock(81344026)");var old=db.pg.queryForList("SELECT id::text,equipment,period,language FROM ai_reports WHERE owner_id=?::uuid AND request_id=?::uuid",owner,request);if(!old.isEmpty()){var r=old.getFirst();if(!r.get("equipment").equals(eq)||!r.get("period").equals(period)||!r.get("language").equals(lang))throw new ResponseStatusException(HttpStatus.CONFLICT,"request-conflict");return (String)r.get("id");}
   if(db.pg.queryForObject("SELECT count(*) FROM ai_reports WHERE owner_id=?::uuid AND status IN ('queued','collecting','analyzing','rendering')",Long.class,owner)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"report-already-running");String next=UUID.randomUUID().toString();boolean configured=ai.configured();db.pg.update("INSERT INTO ai_reports(id,owner_id,request_id,equipment,period,language,cutoff,status,error_code) VALUES(?::uuid,?::uuid,?::uuid,?,?,?,?::timestamptz,?,?)",next,owner,request,eq,period,lang,cutoff.toString(),configured?"queued":"failed",configured?null:"not-configured");return next;});return detail(id);
 }
 Map<String,Object> metadata(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();for(String k:List.of("id","equipment","period","language","status","error_code","snapshot_hash"))out.put(k,row.get(k));for(String k:List.of("created_at","expires_at","updated_at","cutoff"))out.put(k,((java.sql.Timestamp)row.get(k)).toInstant().toString());out.put("expired",((java.sql.Timestamp)row.get("expires_at")).toInstant().isBefore(Instant.now()));return out;}
 Map<String,Object> owned(String id){var rows=db.pg.queryForList("SELECT id,equipment,period,language,status,error_code,snapshot_hash,created_at,expires_at,updated_at,cutoff FROM ai_reports WHERE id=?::uuid AND owner_id=?::uuid",validId(id),AccessSessions.actor().id());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"report-not-found");return rows.getFirst();}
 void available(Map<String,Object> row){if(((java.sql.Timestamp)row.get("expires_at")).toInstant().isBefore(Instant.now()))throw new ResponseStatusException(HttpStatus.GONE,"report-expired");if(!row.get("status").equals("completed"))throw new ResponseStatusException(HttpStatus.CONFLICT,"report-not-completed");}
 @GetMapping public List<Map<String,Object>> list(){return db.pg.queryForList("SELECT id,equipment,period,language,status,error_code,snapshot_hash,created_at,expires_at,updated_at,cutoff FROM ai_reports WHERE owner_id=?::uuid ORDER BY created_at DESC LIMIT 50",AccessSessions.actor().id()).stream().map(this::metadata).toList();}
 @GetMapping("/{id}") public Map<String,Object> detail(@PathVariable String id){var row=owned(id);var out=metadata(row);if(row.get("status").equals("completed")&&!Boolean.TRUE.equals(out.get("expired"))){try{var manifest=(ObjectNode)db.parse(Files.readString(root.resolve(validId(id)).resolve("manifest.json")));var snapshot=(ObjectNode)manifest.get("snapshot");for(var eq:snapshot.path("equipment"))((ObjectNode)eq).remove("timeline");for(var eq:snapshot.path("phm"))for(var pump:eq.path("pumps"))((ObjectNode)pump).remove("trend");for(String field:List.of("kla","vision")){var all=snapshot.path(field);var preview=db.mapper.createArrayNode();for(int i=0;i<Math.min(100,all.size());i++)preview.add(all.get(i));snapshot.set(field,preview);snapshot.put(field+"Total",all.size());}out.put("report",manifest);}catch(Exception e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"report-file-unavailable");}}return out;}
 @GetMapping("/{id}/download") public ResponseEntity<FileSystemResource> download(@PathVariable String id){var row=owned(id);available(row);Path path=root.resolve(validId(id)).resolve("report.xlsx");if(!Files.isRegularFile(path))throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"report-file-unavailable");return ResponseEntity.ok().contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\"cvd-report-"+validId(id)+".xlsx\"").header(HttpHeaders.CACHE_CONTROL,"no-store").body(new FileSystemResource(path));}
 @GetMapping(value="/{id}/charts/{dataset}",produces="image/png") public ResponseEntity<FileSystemResource> chart(@PathVariable String id,@PathVariable String dataset){var row=owned(id);available(row);if(!ReportAi.CHARTS.containsKey(dataset))throw new ResponseStatusException(HttpStatus.NOT_FOUND);Path path=root.resolve(validId(id)).resolve(dataset+".png");if(!Files.isRegularFile(path))throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE);return ResponseEntity.ok().header(HttpHeaders.CACHE_CONTROL,"no-store").body(new FileSystemResource(path));}
 @Scheduled(fixedDelay=2000) void dispatch(){while(slots.tryAcquire()){String id;try{id=tx.execute(t->{var rows=db.pg.queryForList("SELECT id::text FROM ai_reports WHERE status='queued' AND expires_at>now() ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1");if(rows.isEmpty())return null;String next=(String)rows.getFirst().get("id");db.pg.update("UPDATE ai_reports SET status='collecting',updated_at=now() WHERE id=?::uuid",next);return next;});}catch(RuntimeException e){slots.release();return;}if(id==null){slots.release();break;}try{workers.submit(()->{try{run(id);}finally{slots.release();}});}catch(RejectedExecutionException e){slots.release();break;}}}
 void phase(String id,String phase){db.pg.update("UPDATE ai_reports SET status=?,updated_at=now() WHERE id=?::uuid",phase,id);}
 void run(String id){try{var row=db.pg.queryForMap("SELECT equipment,period,language,cutoff FROM ai_reports WHERE id=?::uuid",id);var snapshot=data.collect((String)row.get("equipment"),(String)row.get("period"),((java.sql.Timestamp)row.get("cutoff")).toInstant(),(String)row.get("language"));db.pg.update("UPDATE ai_reports SET snapshot=?::jsonb,snapshot_hash=? WHERE id=?::uuid",snapshot.toString(),ReportData.hash(snapshot),id);phase(id,"analyzing");var analysis=ai.analyze(snapshot);db.pg.update("UPDATE ai_reports SET analysis=?::jsonb WHERE id=?::uuid",analysis.toString(),id);phase(id,"rendering");renderer.render(root.resolve(id),snapshot,analysis,id);phase(id,"completed");}catch(Exception e){db.pg.update("UPDATE ai_reports SET status='failed',error_code=?,updated_at=now() WHERE id=?::uuid",e instanceof ReportFailure r?r.code:"generation-failed",id);deleteFiles(id);}}
 void deleteFiles(String id){try{Path dir=root.resolve(validId(id));if(Files.isDirectory(dir))try(var files=Files.walk(dir)){for(var path:files.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}catch(Exception ignored){/* Cleanup retries on next scheduled sweep. */}}
 @Scheduled(fixedDelay=3600000) void cleanup(){for(var row:db.pg.queryForList("SELECT id::text FROM ai_reports WHERE expires_at<=now()")){String id=(String)row.get("id");deleteFiles(id);db.pg.update("UPDATE ai_reports SET snapshot=NULL,analysis=NULL WHERE id=?::uuid",id);}}
}
